/**
 * The API client. Its types come from the API's own OpenAPI schema (api-types.ts, generated by
 * bin/openapi.sh), so a changed response shape fails type-checking here instead of at runtime.
 */

import type { components } from "./api-types";

export type Health = components["schemas"]["Health"];

/** A request that failed: its HTTP status (0 when the server could not be reached) and why. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

export class Api {
  constructor(
    private readonly base = "/api",
    private readonly fetcher: typeof fetch = (...args) => fetch(...args),
  ) {}

  /** Whether the server and its database answer, and the server's version. */
  health(): Promise<Health> {
    return this.get<Health>("/health");
  }

  private async get<T>(path: string): Promise<T> {
    let response: Response;
    try {
      response = await this.fetcher(this.base + path, {
        headers: { Accept: "application/json" },
        credentials: "same-origin",
      });
    } catch (error) {
      throw new ApiError(0, error instanceof Error ? error.message : String(error));
    }
    if (!response.ok) {
      throw new ApiError(response.status, await detail(response));
    }
    return (await response.json()) as T;
  }
}

/** The server's own explanation of a failure, when it gave one, else the status text. */
async function detail(response: Response): Promise<string> {
  try {
    const body = (await response.json()) as { detail?: unknown };
    if (typeof body.detail === "string") return body.detail;
  } catch {
    // Not JSON: fall through to the status text.
  }
  return response.statusText || `HTTP ${response.status}`;
}
